import cv2, glob, numpy as np

frames = sorted(glob.glob('/root/keyframes_*.png'))

def load_gray(path):
    return cv2.imread(path, cv2.IMREAD_GRAYSCALE)

tmpl = load_gray('/root/coin.png')
(h, w) = tmpl.shape[:2]

# simple NMS based on distance

def nms(points, scores, dist=10):
    if not points:
        return []
    idxs = np.argsort(scores)[::-1]
    picked = []
    for i in idxs:
        x,y = points[i]
        keep = True
        for px,py in picked:
            if (x-px)**2 + (y-py)**2 < dist**2:
                keep = False
                break
        if keep:
            picked.append((x,y))
    return picked

thresholds = [0.7,0.8,0.85,0.9,0.93,0.95]
for t in thresholds:
    counts = []
    for f in frames:
        img = load_gray(f)
        res = cv2.matchTemplate(img, tmpl, cv2.TM_CCOEFF_NORMED)
        ys, xs = np.where(res >= t)
        scores = res[ys, xs]
        pts = list(zip(xs, ys))
        picked = nms(pts, scores, dist=12)
        counts.append(len(picked))
    print('t', t, 'counts', counts)
